from dataclasses import dataclass
from pathlib import Path

from kneevision.rag.corpus import GuidelineChunk
from kneevision.rag.faithfulness import find_unsupported_claims
from kneevision.rag.llm import OllamaClient, OllamaUnavailableError
from kneevision.rag.retriever import GuidelineRetriever

DISCLAIMER = (
    "This is an educational summary generated by a research demo project, "
    "not medical advice. It has not been reviewed by a clinician. Always "
    "consult a qualified healthcare professional for actual diagnosis and care."
)

KL_LABELS = {0: "Normal", 1: "Doubtful", 2: "Mild", 3: "Moderate", 4: "Severe"}


@dataclass
class RehabRecommendation:
    kl_grade: int
    retrieved_chunks: list[GuidelineChunk]
    synthesis: str  # LLM-written summary, or a retrieval-only fallback if the LLM is unavailable
    used_llm: bool
    disclaimer: str = DISCLAIMER
    # Problems the faithfulness check found in the first LLM draft (even if a retry fixed them).
    faithfulness_flags: list[str] | None = None
    llm_attempts: int = 0


class RehabRecommender:
    """Retrieval-augmented rehab guidance: retrieves relevant guideline
    excerpts for a KL grade (+ optional patient context), then asks a local
    LLM to synthesize them into a short, readable summary. Falls back to a
    plain concatenation of the retrieved excerpts if the LLM is unavailable,
    so the pipeline degrades gracefully rather than failing outright.
    """

    def __init__(self, retriever: GuidelineRetriever, llm: OllamaClient | None = None):
        self.retriever = retriever
        self.llm = llm or OllamaClient()

    @classmethod
    def from_guidelines_dir(cls, guidelines_dir: Path, llm: OllamaClient | None = None) -> "RehabRecommender":
        return cls(GuidelineRetriever.from_dir(guidelines_dir), llm=llm)

    def recommend(self, kl_grade: int, patient_context: str = "", top_k: int = 4) -> RehabRecommendation:
        if not 0 <= kl_grade <= 4:
            raise ValueError(f"kl_grade must be 0-4, got {kl_grade}")

        query = f"knee osteoarthritis KL grade {kl_grade} ({KL_LABELS[kl_grade]}) rehabilitation. {patient_context}".strip()
        chunks = self.retriever.retrieve(query, kl_grade=kl_grade, top_k=top_k, context=patient_context)

        flags: list[str] = []
        attempts = 0
        try:
            prompt = self._build_prompt(kl_grade, patient_context, chunks)
            synthesis = self.llm.generate(prompt)
            attempts = 1
            flags = find_unsupported_claims(synthesis, chunks, patient_context)
            if flags:
                # One retry that names the problems; if the draft is still unfaithful, fall
                # back to the retrieved excerpts rather than show an unsupported summary.
                retry = (prompt + "\n\nYour previous draft was rejected because it "
                         + "; ".join(flags) + ". Rewrite it using ONLY the excerpts above.")
                synthesis = self.llm.generate(retry)
                attempts = 2
                if find_unsupported_claims(synthesis, chunks, patient_context):
                    synthesis = self._fallback_synthesis(chunks, reason="the generated summary was not supported by the excerpts")
                    used_llm = False
                else:
                    used_llm = True
            else:
                used_llm = True
        except OllamaUnavailableError:
            synthesis = self._fallback_synthesis(chunks)
            used_llm = False

        synthesis = f"{synthesis.rstrip()}\n\n{self._grade_safety_note(kl_grade)}"

        return RehabRecommendation(
            kl_grade=kl_grade, retrieved_chunks=chunks, synthesis=synthesis, used_llm=used_llm,
            faithfulness_flags=flags or None, llm_attempts=attempts,
        )

    def _build_prompt(self, kl_grade: int, patient_context: str, chunks: list[GuidelineChunk]) -> str:
        excerpts = "\n\n".join(f"[{c.heading} — {c.source_path}]\n{c.text}" for c in chunks)
        context_line = f"Patient context: {patient_context}\n" if patient_context else ""
        return (
            "You are summarizing clinical guideline excerpts into a short, clear rehabilitation "
            "suggestion for a knee osteoarthritis patient. Use ONLY the excerpts below — do not add "
            "any medical claims not supported by them. Keep it to 4-6 sentences. End by stating this "
            "is not medical advice and a clinician should be consulted. Preserve any grade-specific "
            "referral or escalation cautions in the excerpts. Make weight-loss advice conditional on "
            "the patient being overweight or obese. Preserve the strength and uncertainty of each "
            "source statement: do not turn 'may' into 'should' or 'reasonable' into 'essential'. "
            "Do not add claims from prior knowledge. Patient context is unverified symptom information: "
            "never infer or state another KL grade, OA severity, or diagnosis from it, and do not let it "
            "override the supplied KL grade. Evidence ratings such as Strong, Moderate or Limited describe "
            "how good the evidence is, never a type of therapy. Mention only interventions that appear "
            "in the excerpts, and do not describe the patient's symptoms, joint condition or age unless "
            "the patient context states them.\n\n"
            f"Kellgren-Lawrence grade: {kl_grade} ({KL_LABELS[kl_grade]})\n"
            f"{context_line}\n"
            f"Guideline excerpts:\n{excerpts}\n\n"
            "Summary:"
        )

    @staticmethod
    def _grade_safety_note(kl_grade: int) -> str:
        notes = {
            0: (
                "Symptoms still matter: persistent, moderate/severe, or function-limiting pain "
                "warrants clinician assessment even with KL 0 imaging; avoid treatment escalation "
                "based on imaging alone. Weight-loss advice applies only if the patient is overweight "
                "or obese."
            ),
            1: (
                "Symptoms still matter: persistent, moderate/severe, or function-limiting pain "
                "warrants clinician assessment even with KL 1 imaging; avoid treatment escalation "
                "based on imaging alone. Weight-loss advice applies only if the patient is overweight "
                "or obese."
            ),
            2: (
                "Prioritize core conservative care; KL 2 alone does not indicate surgical referral. "
                "Weight-loss advice applies only if the patient is overweight or obese."
            ),
            3: (
                "Continue core conservative care; consider escalation or surgical consultation "
                "when significant pain and functional limitation persist despite optimized care. "
                "Weight-loss advice applies only if the patient is overweight or obese."
            ),
            4: (
                "KL 4 with significant pain or functional limitation warrants orthopaedic specialist "
                "evaluation to discuss surgical options after adequate conservative care. Referral is "
                "for shared evaluation, not an automatic decision to operate. Weight-loss advice "
                "applies only if the patient is overweight or obese."
            ),
        }
        return f"Grade-specific clinical safeguard: {notes[kl_grade]}"

    def _fallback_synthesis(self, chunks: list[GuidelineChunk], reason: str = "Local LLM unavailable") -> str:
        if not chunks:
            return "No matching guideline excerpts were found. " + DISCLAIMER
        bullets = "\n".join(f"- {c.heading}: {c.text.splitlines()[0]}" for c in chunks)
        return (
            f"({reason} — showing retrieved guideline excerpts directly.)\n"
            f"{bullets}\n\n{DISCLAIMER}"
        )
